import * as THREE from 'three/webgpu';
import { 
  positionLocal, 
  normalLocal, 
  uv, 
  texture, 
  add, 
  mul, 
  sub, 
  float,
} from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(-2.5, -1.1, 0);

  // Create high-tessellation plane for displacement mapping
  const geometry = new THREE.PlaneGeometry(1, 1, 64, 64);

  // Load textures via cached context loaders
  const colorTexture = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.png');
  const depthTexture = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.depth.png');

  // Configure texture properties for quality
  colorTexture.colorSpace = THREE.SRGBColorSpace;
  colorTexture.magFilter = THREE.LinearFilter;
  colorTexture.minFilter = THREE.LinearMipmapLinearFilter;

  depthTexture.magFilter = THREE.LinearFilter;
  depthTexture.minFilter = THREE.LinearMipmapLinearFilter;

  // Create TSL nodes for displacement
  const colorNode = texture(colorTexture, uv());
  const depthNode = texture(depthTexture, uv());

  // Displacement calculation: (depth - 0.5) * 0.05
  const displacement = mul(
    sub(depthNode, float(0.5)),
    float(0.05)
  );

  // Displace vertices along surface normal
  const displacedPosition = add(
    positionLocal,
    mul(normalLocal, displacement)
  );

  // Create machined-metal PBR material
  const material = new THREE.MeshPhysicalNodeMaterial({
    colorNode: colorNode,
    positionNode: displacedPosition,
    metalness: 0.4,
    roughness: 0.6,
    clearcoat: 0.15,
    clearcoatRoughness: 0.5,
    anisotropy: 0.3,
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Apply cinematic primitives
  if (ctx.primitives.parallaxScroll) {
    ctx.primitives.parallaxScroll(mesh, { intensity: 0.4 });
  }

  if (ctx.primitives.depthRotate) {
    ctx.primitives.depthRotate(mesh, { maxDeg: 8 });
  }

  // Setup GSAP animation timeline
  const timeline = gsap.timeline({ paused: true });
  let isHovering = false;

  // Event handlers
  group.userData.handlers = {
    onHover: (hovered) => {
      if (hovered && !isHovering) {
        isHovering = true;
        // Rise-in effect: +0.15 units, power3.out easing, 0.7s duration
        timeline.to(group.position, {
          y: -1.1 + 0.15,
          duration: 0.7,
          ease: 'power3.out'
        }, 0);
      } else if (!hovered && isHovering) {
        isHovering = false;
        // Return to original position
        timeline.to(group.position, {
          y: -1.1,
          duration: 0.7,
          ease: 'power3.out'
        }, 0);
      }
    },
    onClick: () => {
      group.dispatchEvent({ type: 'hub-home.select' });
    }
  };

  // Cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    colorTexture.dispose();
    depthTexture.dispose();
    timeline.kill();
  };

  return group;
}
